# 전통적인 OOP 방식
class Player:
    def __init__(self):
        self.x, self.y = 0, 0
        self.health = 100
        self.speed = 5

    def move(self, dx, dy):
        self.x += dx * self.speed
        self.y += dy * self.speed

    def take_damage(self, damage):
        self.health -= damage

# DOP 방식 - 데이터와 로직 완전 분리
entities = [
    {"id": 1, "position": {"x": 0, "y": 0}, "health": 100, "speed": 5, "type": "player"},
    {"id": 2, "position": {"x": 10, "y": 5}, "health": 50, "speed": 3, "type": "enemy"},
    {"id": 3, "position": {"x": 15, "y": 8}, "health": 30, "speed": 7, "type": "enemy"}
]

# 순수 함수들로 시스템 구현
def move_system(entities, dt):
    return [
        {**entity, "position": {
            "x": entity["position"]["x"] + entity.get("velocity_x", 0) * dt,
            "y": entity["position"]["y"] + entity.get("velocity_y", 0) * dt
        }} if "position" in entity else entity
        for entity in entities
    ]

def combat_system(entities, damage_events):
    entity_map = {e["id"]: e for e in entities}

    for event in damage_events:
        if event["target_id"] in entity_map:
            target = entity_map[event["target_id"]]
            entity_map[event["target_id"]] = {
                **target,
                "health": max(0, target["health"] - event["damage"])
            }

    return list(entity_map.values())
```

