# DOP 스타일 데이터 변환 파이프라인
def calculate_order_total(order):
    return {
        **order,
        "total": sum(p["price"] * p["qty"] for p in order["products"])
    }

def add_customer_segment(orders_with_totals):
    return [
        {
            **order,
            "segment": "VIP" if order["total"] > 1000000 else "Regular"
        }
        for order in orders_with_totals
    ]

# 파이프라인 실행
processed_orders = (
    orders
    |> map(calculate_order_total)
    |> list
    |> add_customer_segment
)

# 고객별 집계
from collections import defaultdict

def aggregate_by_customer(orders):
    customer_stats = defaultdict(lambda: {"total_spent": 0, "order_count": 0})

    for order in orders:
        cid = order["customer_id"]
        customer_stats[cid]["total_spent"] += order["total"]
        customer_stats[cid]["order_count"] += 1

    return dict(customer_stats)
