## 🌐 웹 API에서의 DOP

```python
# FastAPI + DOP 스타일
from typing import Dict, List

# 데이터 스키마 (순수 데이터)
UserData = Dict[str, Any]
PostData = Dict[str, Any]

# 순수 함수들
def validate_user(user_data: UserData) -> UserData:
    required_fields = ["email", "name"]

    if not all(field in user_data for field in required_fields):
        raise ValueError("Missing required fields")

    return {
        **user_data,
        "created_at": datetime.now().isoformat(),
        "status": "active"
    }

def hash_password(user_data: UserData) -> UserData:
    if "password" in user_data:
        return {
            **user_data,
            "password_hash": bcrypt.hashpw(user_data["password"].encode(), bcrypt.gensalt())
        }
    return user_data

def remove_sensitive_data(user_data: UserData) -> UserData:
    safe_fields = ["id", "email", "name", "created_at", "status"]
    return {k: v for k, v in user_data.items() if k in safe_fields}

# 컨트롤러에서 파이프라인 구성
@app.post("/users")
async def create_user(user_input: dict):
    try:
        processed_user = (
            user_input
            |> validate_user
            |> hash_password
            |> save_to_database  # 데이터베이스도 순수 함수로
            |> remove_sensitive_data
        )
        return {"success": True, "user": processed_user}
    except ValueError as e:
        return {"success": False, "error": str(e)}
