# 애플리케이션 상태
app_state = {
    "users": [],
    "current_user": None,
    "loading": False,
    "error": None
}

# 액션 (순수 데이터)
actions = {
    "LOGIN_START": {"type": "LOGIN_START"},
    "LOGIN_SUCCESS": {"type": "LOGIN_SUCCESS", "payload": {"user": {...}}},
    "LOGIN_FAILURE": {"type": "LOGIN_FAILURE", "payload": {"error": "Invalid credentials"}}
}

# 리듀서 (순수 함수)
def user_reducer(state, action):
    action_type = action["type"]

    if action_type == "LOGIN_START":
        return {**state, "loading": True, "error": None}

    elif action_type == "LOGIN_SUCCESS":
        return {
            **state,
            "current_user": action["payload"]["user"],
            "loading": False,
            "error": None
        }

    elif action_type == "LOGIN_FAILURE":
        return {
            **state,
            "current_user": None,
            "loading": False,
            "error": action["payload"]["error"]
        }

    return state
```

